import threading

class SafeCounter:
    def __init__(self):
        self._value = 0
        self._lock = threading.Lock()

    @property
    def value(self):
        with self._lock:
            return self._value

    def increment(self):
        with self._lock:
            self._value += 1


def count_with_threads(n_threads: int, increments: int) -> int:
    counter = SafeCounter()
    threads = []

    def worker(counter, increments):
        for _ in range(increments):
            counter.increment()

    for _ in range(n_threads):
        thread = threading.Thread(target=worker, args=(counter, increments))
        thread.start()
        threads.append(thread)

    for thread in threads:
        thread.join()

    return counter.value
